function Player2DFramePanel:_RefreshAllFrames()
    self.frameIdList = {} -- int[]; 6270000 这种值
    self.frameMap = {}

    self.ownedFrames   = PlayerInfoUtils.GetItemHasByKind(Constants.PlayerAvatarItemType.Theme)
    local unlockedFrameIdList  = table.keys(self.ownedFrames) -- 已到手(已解锁) 的 frame ids, string "6270000" 这种值
    -- string -> int
    for i=1,#unlockedFrameIdList do 
        unlockedFrameIdList[i] = checkInt( unlockedFrameIdList[i] ) -- int
    end
    -- 整理排序: 已经获得的排前面, 再按 id 大小排
    table.sort(unlockedFrameIdList, function(IdA, IdB)
        return IdA < IdB
    end)

    ---
    local allFrameIdList = PlayerInfoUtils.GetItemIdsByKind(Constants.PlayerAvatarItemType.Theme) -- 配表中全体 Frame 的 ids, type = string
    
    --  
    for k,idInt in pairs(unlockedFrameIdList) do -- id:int
        table.insert( self.frameIdList, idInt )
        self.frameMap[checkInt(idInt)] = { state = Player2DStates.FrameState.UnLocked }
    end 
    for k,idStr in pairs(allFrameIdList) do 
        local idInt = tonumber(idStr)
        if table.indexof( unlockedFrameIdList, idInt ) == false then 
            table.insert( self.frameIdList, idInt )
            self.frameMap[checkInt(idInt)] = { state = Player2DStates.FrameState.Locked }
        end
    end

    -- 正在展示的 frame 数据
    self.selectedFrameId_ = checkInt( self:GetPlayerData().playerThemeId )
    self:SetSelectedIndex( self:GetFrameIndexById(self.selectedFrameId_) )

    --- 绘制 左侧 列表:
    local totalNum = #self.frameIdList
    if not self.FrameList.IsListViewInit then
        self.FrameList:InitListView(totalNum, Bind(self, self.OnGetFrameCell))
    else
        GameUtils.ReloadData(self.FrameList, totalNum)
    end    
end


-- 将模板主题 使用到 页面上去
function Player2DFramePanel:_DrawFrame()
    local frameId = self:GetSelectedFrameId()
    local vo = PlayerInfoUtils.GetHeadAvatarVo(frameId)
    local framePicPath = vo.thumbnailPath
    local prefabName = vo.prefabName

    if string.isEmpty(framePicPath) then 
        -- 使用 默认主题:
        CfUtils.SetActive(self.ImgBgpanel, true)
        CfUtils.SetActive(self.ImgFrame,    false)
    else 
        -- 使用 定制主题:
        CfUtils.SetActive(self.ImgBgpanel, false)
        CfUtils.SetActive(self.ImgFrame,    true)
        CfUtils.FillImage(self.ImgFrame, framePicPath)
    end 
end


function Player2DFramePanel:RefreshAll()
    self:_RefreshAllFrames()
    self:_DrawFrame()
end


