---@return boolean
function Player2DFramePanel:IsLockedFrame(frameId_)
    return (self.frameMap[checkInt(frameId_)].state == Player2DStates.FrameState.Locked)    
end

function Player2DFramePanel:IsShowMySelf()
    return checkBool(KCookie.Get("PersonalInfoDisplayIsMyself"))
end

-- 切换 选中的 frame元素:
function Player2DFramePanel:SetSelectedIndex(index)
    local oldIdx = self:GetSelectedIndex()
    self.selectedIndex_ = checkInt(index)
    self:SetSelectedFrameId( self.selectedIndex_, oldIdx )
end


function Player2DFramePanel:GetSelectedIndex()
    return checkInt(self.selectedIndex_)
end



---@param newIdx number @ 1-based index
---@param oldIdx number @ 1-based index
function Player2DFramePanel:SetSelectedFrameId(newIdx, oldIdx)
    --print("SetSelectedFrameId newIdx = " .. tostring(newIdx) .. ", oldIdx = " .. tostring(oldIdx) )
   
    local oldFrameId = self:GetSelectedFrameId() -- cache
    self.selectedFrameId_ = checkInt(self.frameIdList[newIdx])
    
    -- 没修改指向, 啥也不用动:
    if oldFrameId == self:GetSelectedFrameId() then
        return
    end

    if oldIdx>=1 then 
        -- 刷新绘制 左区列表元素:
        local cell = self.FrameList:GetShownItemByItemIndex(oldIdx - 1)
        ---@type Player2DFramePanelCell
        local cellEnv = CfUtils.GetLuaScr(cell, FrameListNodePath)
        if cellEnv then
            cellEnv:UpdateSelectStatus(false)
        else 
            printError("koko - 没找到 ImgSelect 节点")
        end
    end

    if newIdx>=1 then 
        -- 刷新绘制 左区列表元素:
        local cell = self.FrameList:GetShownItemByItemIndex(newIdx - 1)
        ---@type Player2DFramePanelCell
        local cellEnv = CfUtils.GetLuaScr(cell, FrameListNodePath)
        if cellEnv then
            cellEnv:UpdateSelectStatus(true)
        else 
            printError("koko - 没找到 ImgSelect 节点")
        end

        -- update "New"  如果选中的这个 原本是 "New", 那么现在要消除它的 "New" 状态
        local newFrameId = self:GetSelectedFrameId()
        if PlayerInfoUtils.CheckAvatarIsNew(newFrameId) then
            PlayerInfoUtils.UpdateAvatarNewStateById(newFrameId, false)
            if cellEnv then
                cellEnv:UpdateNewMark()
            end
        end
    end

end


function Player2DFramePanel:GetSelectedFrameId()
    return checkInt(self.selectedFrameId_)
end



function Player2DFramePanel:GetFrameIdByIndex(index1Based_)
    return checkInt(self.frameIdList[index1Based_])
end


---@return number @ 1-based index
function Player2DFramePanel:GetFrameIndexById(frameId_)
    for i=1, #self.frameIdList do
        if self.frameIdList[i] == frameId_ then 
            return i
        end 
    end
    printError("没找到, 参数: " .. tostring(frameId_))
    return 1
end



function Player2DFramePanel:GetPlayerData()
    return checkTable(KCookie.Get("PersonalInfoDisplayDt"))
end


