-- 存储选中的 主题
function Player2DFramePanel:WhenClickBtn_Save()
    --print("koko - Player2DFramePanel:WhenClickBtn_Save")

    local currentFrameId = self:GetSelectedFrameId()
    local isSelectedFrameId = currentFrameId == self:GetSelectedFrameId()

    -- !! 若选择了 未解锁主题, 此时调用后端接口, 后端会返回并显示错误信息
    -- if self.frameMap[currentFrameId].state == Player2DStates.FrameState.Locked then 
    --     GameUtils.Toast( localize("无法保存") ) -- 飘字
    --     return
    -- end

    GameUtils.Request(Interfaces.PlayerSetAvatar, {type = Constants.PlayerAvatarItemType.Theme,  avatar = currentFrameId}, function(request, response)
        if checkInt(response.errCode) == 0 then
            -- 改写本地数据:  右侧主题区数据
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            playerComponent.playerDojo.playerPanel = currentFrameId
            ---
            Events.Broadcast(Constants.EventNames.Player2DRefreshPlayerData, nil) -- 重读 PlayerData
            self:_RefreshAllFrames()
            self:_DrawFrame()
            GameUtils.Toast( localize("保存成功") ) -- 飘字
        end
    end)
end 




function Player2DFramePanel:OnGetFrameCell(listView, index0Based)
    if index0Based < 0 then return end
    local cell = listView:NewListViewItem(FrameListNodeName)
    self:_RefreshItemCell(cell, index0Based+1)
    return cell
end


-- 绘制一个 左侧列表中的主题
function Player2DFramePanel:_RefreshItemCell(node, index1Based)

    local frameId = checkInt(self:GetFrameIdByIndex(index1Based))
    local isSelectedFrameId = frameId == self:GetSelectedFrameId()

    ---@type Player2DFramePanelCell
    local cellEnv = CfUtils.GetLuaScr(node, FrameListNodePath)

    cellEnv:SetLuaIndex(index1Based)
    
    cellEnv:SetCellData({
        frameId  = frameId,
        isSelected = isSelectedFrameId,
        isSelect = frameId == self:GetSelectedFrameId(),
        isLocked = self:IsLockedFrame(frameId),
        isMySelf = self:IsShowMySelf(),
    })
    
    cellEnv:SetClickFrameCB(function(clickIndex)
        self:SetSelectedIndex(clickIndex) -- 这样设置一定不会是 -1 

        Events.Broadcast(Constants.EventNames.Player2DMainRefreshTitle, nil) -- 重绘 主场景 顶部页签 (的 "New" 标准) -- !! 不完善

        self:_DrawFrame()

        local cellData = cellEnv:GetCellData()
        local isLocked = (cellData.isLocked == true)
        local goodsVo =  PlayerInfoUtils.GetHeadAvatarVo(cellData.frameId) -- 62头像头像框道具表
        --printError("选中: " ..tostring(clickIndex).."; isLocked:"..tostring(isLocked))

        CfUtils.SetActive(self.FrameLocktxt, isLocked)
        if isLocked == true then 
            CfUtils.FillText( self.LocktxtTitle, goodsVo.name )
            CfUtils.FillText( self.LocktxtDesc, goodsVo.description )
        end 

